Running command: cd /workspace/repo-vul/src-vul/capstonenext && python3 - <<'PY'
import re,glob
for path in glob.glob('arch/**/*.[ch]',recursive=True)+glob.glob('arch/**/*.inc',recursive=True):
    try:s=open(path,errors='ignore').read().splitlines()
    except: continue
    for i,l in enumerate(s):
        m=re.search(r'MCOperand_getImm\(MCInst_getOperand\(MI,\s*([^\)]+)\)\)',l)
        if m:
            op=m.group(1).strip()
            ctx='\n'.join(s[max(0,i-5):i+1])
            if f'MCOperand_isImm(MCInst_getOperand(MI, {op}))' not in ctx and f'MCOperand_isImm(MCInst_getOperand(MI,{op}))' not in ctx:
                print(f'{path}:{i+1}: op {op}\n'+ctx+'\n---')
